/* Shared Week / Day / Table renderer. This is a clickable design reference, not a backend. */
(()=>{'use strict';
const M=window.ScheduleModel,H=window.ScheduleHandoff,root=document.getElementById('app'),layers=document.getElementById('layers'),LS='octopos-schedules-handoff-v5';
let S=M.createState(),modal=null,pop=null,tab='audit',timer=null,initialScroll=true,restoreFocus=null;
try{const stored=JSON.parse(localStorage.getItem(LS)||'null');if(stored&&stored.version===5){S={...S,...stored.state};if(!['week','day','table'].includes(S.view))S.view='week';S.permission='owner';S.scenario='normal';S.role='';S.query='';}}catch{}
const paths={calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 10h18"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',left:'<path d="m14 6-6 6 6 6"/>',right:'<path d="m10 6 6 6-6 6"/>',down:'<path d="m6 9 6 6 6-6"/>',plus:'<path d="M12 5v14M5 12h14"/>',search:'<circle cx="10.5" cy="10.5" r="7"/><path d="m16 16 5 5"/>',pin:'<path d="M12 22s7-7 7-13a7 7 0 1 0-14 0c0 6 7 13 7 13z"/><circle cx="12" cy="9" r="2"/>',users:'<circle cx="9" cy="8" r="3"/><path d="M3 20v-2a6 6 0 0 1 12 0v2M17 5a3 3 0 0 1 0 6m2 3a6 6 0 0 1 2 6"/>',check:'<path d="m5 12 4 4L19 6"/>',alert:'<path d="m12 3 10 18H2L12 3zM12 9v5m0 3v1"/>',x:'<path d="m6 6 12 12M6 18 18 6"/>',edit:'<path d="m16 3 5 5L9 20H4v-5zM13 6l5 5"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/>',lock:'<rect x="4" y="11" width="16" height="10" rx="2"/><path d="M8 11V7a4 4 0 0 1 8 0v4"/>',filter:'<path d="M4 6h16M7 12h10m-7 6h4"/>',print:'<path d="M6 9V3h12v6M6 18H3V9h18v9h-3M6 14h12v8H6z"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-9v.1"/>',trash:'<path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7"/>',code:'<path d="m8 5-6 7 6 7M16 5l6 7-6 7M14 3l-4 18"/>',box:'<path d="m3 7 9-4 9 4v10l-9 4-9-4zM3 7l9 5 9-5m-9 5v9"/>',gear:'<circle cx="12" cy="12" r="4"/><path d="M12 2v3m0 14v3M2 12h3m14 0h3M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2"/>',doc:'<path d="M6 3h9l4 4v14H6zM15 3v5h4M9 12h7m-7 4h7"/>',more:'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>',refresh:'<path d="M21 4v6h-6M3 20v-6h6M5 8a8 8 0 0 1 14-3l2 5M3 14l2 5a8 8 0 0 0 14-3"/>'};
const I=(n,z=16)=>`<svg width="${z}" height="${z}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[n]||paths.calendar}</svg>`;
const E=v=>String(v??'').replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
const B=(label,action,cls='',extra='')=>`<button type="button" class="btn ${cls}" data-action="${action}" ${extra}>${label}</button>`;
const editAllowed=()=>S.permission!=='viewer';
const sel=id=>S.highlights.includes(id);
const lit=items=>!S.highlights.length||items.some(x=>sel(x.emp));
const ini=e=>e.name.split(' ').slice(0,2).map(w=>w[0]).join('');
const av=(e,small=false,button=false)=>{let c=M.palette[e.color%12],cl=`av${small?' tiny':''}${sel(e.id)?' selected':''}`;return `<${button?'button':'span'} ${button?`type="button" data-action="highlight" data-id="${e.id}" aria-pressed="${sel(e.id)}" aria-label="${sel(e.id)?'Stop highlighting':'Highlight'} ${E(e.name)}"`:''} class="${cl}" style="--av:${c[1]};--avbg:${c[2]}" title="${E(e.name)}">${ini(e)}</${button?'button':'span'}>`;};
function persist(){try{let state={...S};delete state.scenario;delete state.permission;localStorage.setItem(LS,JSON.stringify({version:5,state}));}catch{}}
function notify(text){const t=document.getElementById('toast');t.textContent=text;clearTimeout(timer);timer=setTimeout(()=>t.textContent='',3300);}
const range=x=>`${M.time(x.start)}–${M.time(x.end)}`;
const dayPast=day=>day<M.today;
const statusForGroup=g=>g.items.reduce((a,x)=>{let k=M.attendance(S,x).kind;a[k]=(a[k]||0)+1;return a;},{ok:0,flag:0,review:0,none:0});
function statusIcon(g){let a=statusForGroup(g);return a.review?`<span class="flag-icon review-icon" title="${a.review} needs review">${I('doc',13)}${a.review}</span>`:a.flag?`<span class="flag-icon" title="${a.flag} attendance ${a.flag===1?'flag':'flags'}">${I('alert',13)}${g.items.length>1?a.flag:''}</span>`:a.ok===g.items.length?`<span class="ok-icon" title="All recorded within the attendance window">${I('check',10)}</span>`:'';}
function sidebar(){return `<aside class="sidebar"><a href="#" class="nav" data-action="nav" data-name="Dashboard">${I('calendar')}Dashboard</a><div class="nav group">${I('users')}HR</div><button class="nav sub" data-action="employees">Employees</button><button class="nav sub" data-action="nav" data-name="Roles">Roles</button><a class="nav sub current" href="#" data-action="home">Employee Schedules</a>${[['box','Products'],['box','Purchasing'],['users','Customer Engagement'],['doc','Reports'],['gear','Settings']].map(([i,n])=>`<button class="nav" data-action="nav" data-name="${n}">${I(i)}${n}</button>`).join('')}<div class="sidebar-foot">Design review prototype<br>Employee Schedules · V5</div></aside>`;}
function legend(){return `<div class="legend" aria-label="Schedule legend"><span><i class="sw"></i>Past shifts</span><span><i class="sw planned"></i>Scheduled shift</span><span><i class="sw once"></i>One-time shift</span><span><i class="sw closed"></i>Store closed</span></div>`;}
function highlightStack(){let p=M.people(S),front=p.slice(0,8),n=p.length-front.length,hiddenSelected=S.highlights.filter(id=>!p.some(e=>e.id===id)).length;return `<div class="highlights"><span>Highlight:</span><div class="avatar-stack">${front.map(e=>av(e,false,true)).join('')}${n?`<button class="av moreav" data-action="morePeople" aria-label="Highlight more employees, ${n} more" aria-expanded="${pop?.type==='highlights'}">+${n}</button>`:''}</div>${S.highlights.length?`<span class="hl-status"><span title="${hiddenSelected?hiddenSelected+' outside current filters':'Highlights do not change schedule counts'}">${S.highlights.length} selected${hiddenSelected?'*':''}</span><button class="link" data-action="clearHighlight">Clear</button></span>`:''}</div>`;}
function header(){let dayMode=S.view==='day',label=dayMode?M.formatDate(S.day,{weekday:'long',month:'short',day:'numeric'}):`${M.formatDate(S.week,{day:'2-digit',month:'short'})} – ${M.formatDate(M.add(S.week,6),{day:'2-digit',month:'short'})} ’${S.week.slice(2,4)}`;return `<div class="head"><div class="row between main-heading"><h1>Employee Schedules</h1><div class="row"> <label class="btn loc">${I('pin')}<select id="location" aria-label="Location">${Object.values(M.locations).map(l=>`<option value="${l.id}" ${S.location===l.id?'selected':''}>${l.name}</option>`).join('')}</select></label>${B('Store closures','closures','soft')}${B(I('download')+'<span class="desktop-label">Download schedule</span>','download','primary')}</div></div><div class="toolbar"><div class="row"><div class="date-control">${B(I('left'),'prev','icon','aria-label="Previous '+(dayMode?'day':'week')+'"')}${B(I('calendar')+label,'date','date')}${B(I('right'),'next','icon','aria-label="Next '+(dayMode?'day':'week')+'"')}</div>${B(dayMode?'Today':'This week','today','soft')}${B(I('search')+I('filter'),'toggleFilters',S.filtersOpen||S.query||S.role?'soft':'ghost','aria-label="Search employees and filter roles" aria-expanded="'+S.filtersOpen+'"')}</div><div class="views" role="group" aria-label="Schedule view">${['week','day','table'].map(v=>`<button data-action="view" data-view="${v}" class="${S.view===v?'active':''}" aria-pressed="${S.view===v}">${v[0].toUpperCase()+v.slice(1)}</button>`).join('')}</div></div><div class="secondary">${legend()}${highlightStack()}</div>${S.filtersOpen||S.query||S.role?`<div class="filterline"><label class="searchbox">${I('search')}<input id="employeeSearch" type="search" placeholder="Search employees" aria-label="Search employees" value="${E(S.query)}"></label><label class="row"><span class="help">Employee role</span><select id="roleFilter" class="fieldselect"><option value="">All roles</option>${['Cashier','Stock','Shift Lead','Manager'].map(r=>`<option ${S.role===r?'selected':''}>${r}</option>`).join('')}</select></label>${S.query||S.role?B('Clear filters','clearFilters','ghost small'):''}<span class="help">${M.people(S).length} employees${S.role?' · Role membership, not a shift assignment':''}</span></div>`:''}</div>`;}
function sizing(day){const b=M.bounds(S,day),main=document.querySelector('.page'),width=(main?main.clientWidth:innerWidth-(innerWidth>760?(innerWidth>1100?216:168):0)-50)-44,label=innerWidth<=760?140:154,scale=Math.max(68,Math.floor((width-label)/((b.end-b.start)/60)));return {...b,label,scale,width:Math.round((b.end-b.start)/60*scale),full:Math.round((b.end-b.start)/60*scale+label)};}
const pos=(m,b)=>(m-b.start)/60*b.scale;
function ruler(b){let ticks=[];for(let t=b.start;t<b.end;t+=60)ticks.push(`<button class="tick" style="left:${pos(t,b)}px" data-action="inspectTime" data-time="${t}" aria-label="Inspect scheduled employees at ${M.time(t)}">${M.time(t,false)}</button>`);return `<div class="ruler">${ticks.join('')}</div>`;}
function timelineAxis(b,dayMode=false){return `<div class="axis"><div class="axislabel">${dayMode?'EMPLOYEE':'DAY'}${B(I('info',12),'timelineInfo','ghost small','aria-label="Timeline information"')}</div>${ruler(b)}</div>`;}
function timeDecor(day,b,showLabel=true){let a='';if(day===M.today&&M.now>=b.start&&M.now<=b.end)a=`<div class="elapsed" style="width:${pos(M.now,b)}px"></div><div class="now${showLabel?'':' continuation'}" style="left:${pos(M.now,b)}px">${showLabel?`<span class="now-label">Now · ${M.time(M.now)}</span>`:''}</div>`;return a;}
function gapDecor(day,b,compact=false){return M.gaps(S,day).map(g=>{let w=pos(g.end,b)-pos(g.start,b),text=S.role?`No ${S.role.toLowerCase()}-role employees scheduled`:'No employees scheduled';return `<button class="gap" data-action="gap" data-day="${day}" data-start="${g.start}" data-end="${g.end}" title="${E(text)} · ${range(g)}" aria-label="${E(text)}, ${range(g)}" style="left:${pos(g.start,b)}px;width:${w}px">${!compact&&w>110?text:!compact&&w>25?I('alert',12):''}</button>`}).join('');}
function layoutGroups(gs,b){let lanes=[];return gs.map(g=>{let x=pos(g.start,b)+2,w=Math.max(2,pos(g.end,b)-pos(g.start,b)-4),short=w<220,labelW=190,labelLeft=short&&x+w+labelW+10>b.width;let a=short&&labelLeft?Math.max(2,x-labelW-10):x,z=short&&!labelLeft?Math.min(b.width-2,x+w+labelW+10):x+w;let lane=lanes.findIndex(items=>items.every(v=>z+6<=v.a||a>=v.z+6));if(lane<0){lane=lanes.length;lanes.push([]);}lanes[lane].push({a,z});return {...g,x,w,short,labelLeft,a,z,lane};});}
function bar(g,day,b,top=10,single=false){let chosen=lit(g.items),selected=S.highlights.length&&chosen,phase=day<M.today||day===M.today&&g.end<=M.now?' past':'',origin=g.type==='one-time'?' one-time':'',cl=phase+origin+(chosen?'':' dim')+(selected?' selected':'');let items=g.items.slice().sort((a,b)=>Number(sel(b.emp))-Number(sel(a.emp))||M.emp(S,a.emp).name.localeCompare(M.emp(S,b.emp).name));let n=M.unique(items.map(x=>x.emp)).length,time=range(g),names=items.map(x=>M.emp(S,x.emp).name.split(' ')[0]).join(', ');let target=single?`data-action="shift" data-id="${g.items[0].id}"`:`data-action="group" data-day="${day}" data-key="${g.key}"`;let full=`${n} ${n===1?'employee':'employees'}, ${time}, ${g.items.map(x=>M.emp(S,x.emp).name).join(', ')}`;
 if(g.short){let l=g.labelLeft?g.a:g.x,w=g.z-g.a;return `<button class="short-unit${cl}" ${target} style="left:${l}px;width:${Math.max(30,w)}px;top:${top-3}px" aria-label="${E(full)}" title="${E(full)}"><span class="short-marker" style="left:${g.x-l}px;width:${g.w}px"></span><span class="outside" style="${g.labelLeft?'right:'+(g.z-g.x+8):'left:'+(g.w+8)}px"><b>${single||n===1?E(M.emp(S,items[0].emp).name):n+' employees'} · ${M.dur(g.end-g.start)} ${statusIcon(g)}</b><small>${time}</small></span></button>`;}
 let maxAv=g.w<360?1:3,show=items.slice(0,maxAv);return `<button class="shift${cl}${single?' individual':''}" ${target} style="left:${g.x}px;width:${g.w}px;top:${top}px" aria-label="${E(full)}" title="${E(full)}">${!single?`<span class="avatars">${show.map(x=>av(M.emp(S,x.emp),true)).join('')}${n>maxAv?`<span class="groupcount">+${n-maxAv}</span>`:''}</span>${n>1?`<span class="groupcount">${n} people</span>`:''}${g.w>430?`<span class="names">${E(names)}</span>`:''}`:''}<span class="range">${time}</span>${statusIcon(g)}</button>`;}
function weekView(){let b=sizing(),days=M.week(S.week);return `<div class="calendar-shell"><div class="viewport" id="viewport"><div class="calendar" style="width:${b.full}px;--scale:${b.scale}px;--label:${b.label}px">${timelineAxis(b)}${days.map(day=>{let gs=layoutGroups(M.groups(S,day),b),close=M.closure(S,day),off=M.timeOff(S,day).filter(o=>M.people(S).some(e=>e.id===o.emp)),lanes=Math.max(1,...gs.map(g=>g.lane+1)),top=day===M.today?27:10,h=Math.max(75,top+lanes*48+(off.length?20:5)+(close&&gs.length?24:0)),count=M.unique(M.shifts(S,day,true).map(x=>x.emp)).length;return `<section class="week-row ${dayPast(day)?'past':''}" data-day="${day}"><button class="day-label" data-action="openDay" data-day="${day}" aria-label="Open ${M.formatDate(day)}"><span class="dateword"><span class="circle ${day===M.today?'today':''}">${Number(day.slice(8))}</span><span><b>${M.formatDate(day,{weekday:'short'})}</b><small>${M.formatDate(day,{month:'short',year:'numeric'})}</small></span></span><div class="sub">${close?count?count+' scheduled · closed':'Store closed':count+' employees scheduled'}</div></button><div class="lane ${close?'closed-lane':''}" style="height:${h}px">${close?`<div class="closed-note">${I('lock',12)} Store closed · ${E(close.name)}${count?' · working exception':''}</div>`:gapDecor(day,b)}${timeDecor(day,b)}${gs.map(g=>bar(g,day,b,top+g.lane*48+(close?24:0))).join('')}${off.length?`<button class="timeoff-inline" data-action="timeoff" data-day="${day}">Time off · ${off.map(o=>E(M.emp(S,o.emp).name)).join(', ')}</button>`:''}${!gs.length&&!close&&editAllowed()&&day>=M.today?`<button class="add-empty" data-action="addShift" data-day="${day}">${I('plus',12)} Add shift</button>`:''}</div></section>`;}).join('')}</div></div></div>`;}
function dayView(){const day=S.day,b=sizing(day),all=M.shifts(S,day,true),gs=M.groups(S,day),off=M.timeOff(S,day).filter(o=>M.people(S).some(e=>e.id===o.emp)),close=M.closure(S,day),free=M.people(S).filter(e=>!all.some(x=>x.emp===e.id)&&!off.some(o=>o.emp===e.id&&o.start===0));let first=true;
 const row=(x)=>{let e=M.emp(S,x.emp),g=layoutGroups([{start:x.start,end:x.end,type:x.type,items:[x]}],b)[0],showNowLabel=first;first=false;return `<div class="employee-row ${sel(e.id)?'selected':''}"><button class="employee-cell" data-action="employee" data-id="${e.id}">${av(e)}<span class="who"><b>${E(e.name)}</b><small>${E(e.roles.join(', '))}</small></span></button><div class="lane">${gapDecor(day,b,true)}${timeDecor(day,b,showNowLabel)}${bar(g,day,b,9,true)}</div></div>`;};
 let body=gs.map(g=>{let id=day+'|'+g.key,collapsed=S.closedGroups.includes(id);return `${g.items.length>1?`<div class="day-group"><button data-action="collapseGroup" data-key="${id}" aria-expanded="${!collapsed}">${I(collapsed?'right':'down',12)}${range(g)} <span class="group-meta">${M.unique(g.items.map(x=>x.emp)).length} employees${g.type==='one-time'?' · One-time':''}</span></button></div>`:''}${collapsed?'':g.items.map(row).join('')}`;}).join('');
 if(off.length)body+=`<div class="day-group"><button data-action="toggleOff" aria-expanded="${S.showOff}">${I(S.showOff?'down':'right',12)}Time off <span class="group-meta">${off.length} employees</span></button></div>${S.showOff?off.map(o=>`<div class="employee-row"><button class="employee-cell" data-action="employee" data-id="${o.emp}">${av(M.emp(S,o.emp))}<span class="who"><b>${E(M.emp(S,o.emp).name)}</b></span></button><div class="lane"><span class="timeoff-bar" ${o.start?`style="left:${pos(o.start,b)}px;width:${pos(o.end,b)-pos(o.start,b)}px;right:auto"`:''}>${o.label}</span></div></div>`).join(''):''}`;
 if(free.length)body+=`<div class="day-group"><button data-action="toggleFree" aria-expanded="${S.showFree}">${I(S.showFree?'down':'right',12)}Not scheduled <span class="group-meta">${free.length} employees · ${S.showFree?'Hide':'Show'}</span></button></div>${S.showFree?free.map(e=>`<div class="employee-row"><button class="employee-cell" data-action="employee" data-id="${e.id}">${av(e)}<span class="who"><b>${E(e.name)}</b></span></button><div class="lane">${editAllowed()&&day>=M.today?`<button class="add-empty" data-action="addShift" data-day="${day}" data-emp="${e.id}">${I('plus',12)} Add shift</button>`:`<span class="timeoff-inline">No shift scheduled</span>`}</div></div>`).join(''):''}`;
 return `<div class="calendar-shell"><div class="viewport" id="viewport"><div class="calendar" style="width:${b.full}px;--scale:${b.scale}px;--label:${b.label}px">${timelineAxis(b,true)}${close?`<div class="closed-note closed-lane">${I('lock',12)} Store closed · ${E(close.name)}${all.length?' · Scheduled working exceptions shown below':''}</div>`:''}${body||`<div class="empty"><h3>No shifts scheduled</h3><p>Choose another day or add a shift.</p></div>`}</div></div></div>`;}
function tableView(){let ds=M.week(S.week),p=M.people(S),all=ds.flatMap(day=>M.shifts(S,day,true)),tot=M.aggregate(S,all);let rows=p.map(e=>{let et=M.aggregate(S,all.filter(x=>x.emp===e.id));return `<tr class="${sel(e.id)?'selected':''}"><td><button class="empbtn" data-action="employee" data-id="${e.id}">${av(e)}<span><b>${E(e.name)}</b><small>${M.dur(et.minutes)} planned · ${M.money(e.wage)}/hr</small></span></button></td>${ds.map(day=>{let arr=all.filter(x=>x.day===day&&x.emp===e.id),closed=M.closure(S,day),off=M.timeOff(S,day).find(o=>o.emp===e.id);return `<td class="${closed?'closed':''}">${arr.map(x=>{let a=M.attendance(S,x),isPast=day<M.today||day===M.today&&x.end<=M.now;return `<button class="shift table-shift ${isPast?'past':''} ${x.type==='one-time'?'one-time':''} ${lit([x])?'':'dim'}" data-action="shift" data-id="${x.id}" aria-label="${E(e.name)}, ${M.formatDate(day)}, ${range(x)}"><div class="range">${range(x)}</div><div class="second"><span>${M.dur(M.totals(S,x).paid)} planned</span>${statusIcon({items:[x]})}</div></button>`;}).join('')}${off&&!closed?`<div class="help">${off.start?'AM off':'Time off'}</div>`:''}${!arr.length&&!closed&&!off&&editAllowed()&&day>=M.today?`<button class="empty-cell" data-action="addShift" data-day="${day}" data-emp="${e.id}">${I('plus',12)} Add shift</button>`:''}</td>`;}).join('')}</tr>`;}).join('');return `<div class="calendar-shell"><div class="tablewrap" id="viewport"><table class="roster"><thead><tr><th scope="col">Employee</th>${ds.map(day=>`<th scope="col"><button class="link" data-action="openDay" data-day="${day}" style="color:${day===M.today?'var(--blue)':'inherit'};font-size:10px">${M.formatDate(day,{weekday:'short',day:'numeric',month:'short'})}</button>${M.closure(S,day)?'<span class="closed-title">Store closed</span>':''}</th>`).join('')}</tr></thead><tbody>${rows}</tbody><tfoot><tr><td><div class="help">Planned hours · Est. cost</div><div class="total-cell"><span>${M.dur(tot.minutes)}</span><b>${M.money(tot.cost)}</b></div></td>${ds.map(day=>{let dt=M.aggregate(S,all.filter(x=>x.day===day));return `<td><div class="total-cell"><span>${M.dur(dt.minutes)}</span><b>${M.money(dt.cost)}</b></div></td>`;}).join('')}</tr></tfoot></table></div></div>`;}
function empty(title,text,button,action,ico='calendar'){return `<div class="calendar-shell"><div class="empty"><div class="art">${I(ico,25)}</div><h3>${title}</h3><p>${text}</p>${button?B(button,action,'soft'):''}</div></div>`;}
function content(){if(S.scenario==='disabled')return empty('Shift tracking is turned off','Turn it on in Location Settings → Time Clock to schedule employees and track breaks.','Go to Time Clock settings','settings');if(S.scenario==='loading')return '<div class="calendar-shell"><div class="skeleton" aria-busy="true" aria-label="Loading schedules">'+Array.from({length:7},(_,i)=>`<div style="width:${85-i%3*15}%"></div>`).join('')+'</div></div>';if(S.scenario==='error')return empty('Schedules couldn’t load','Your schedule hasn’t changed. Try loading it again.','Retry','retry','refresh');if(S.scenario==='noemployees')return empty('No employees at this location','Add a work location in an employee’s Basic Details to include them here.','Go to Employees','employees','users');if(S.scenario==='nosetup')return empty('No usual working hours set','Set usual working hours for employees in Employees → Shift Details to start building their schedule.','Go to Employees','employees');if(S.scenario==='emptyweek'&&!M.week(S.week).some(d=>M.shifts(S,d).length))return empty('No shifts scheduled for this week','Choose another week or add a one-time shift.','Add shift','addShift');if(!M.people(S).length)return empty('No employees match your filters','Try another name or clear the role filter.','Clear filters','clearFilters','search');return S.view==='table'?tableView():S.view==='day'?dayView():weekView();}
function printable(){let ds=S.view==='day'?[S.day]:M.week(S.week);return `<section class="print-area"><h1>${M.locations[S.location].name} · Employee schedules</h1><p>${M.formatDate(ds[0])}–${M.formatDate(ds.at(-1))} · ${M.locations[S.location].timezone} · Planned hours, not actual attendance</p><table><thead><tr><th>Employee</th>${ds.map(d=>`<th>${M.formatDate(d)}</th>`).join('')}</tr></thead><tbody>${M.people(S).map(e=>`<tr><th>${E(e.name)}</th>${ds.map(d=>`<td>${M.shifts(S,d,true).filter(x=>x.emp===e.id).map(x=>`${range(x)} (${M.dur(M.totals(S,x).paid)} planned)`).join('<br>')|| (M.closure(S,d)?'Store closed':'—')}</td>`).join('')}</tr>`).join('')}</tbody></table></section>`;}
function render(){captureDraft();let vp=document.getElementById('viewport'),scroll=vp?{top:vp.scrollTop,left:vp.scrollLeft}:null,f=document.activeElement,focus=f?.id?{id:f.id,start:f.selectionStart,end:f.selectionEnd}:null;root.innerHTML=`<header class="top"><span class="logo">octopos</span><div class="topsearch">${I('search',14)}Search<kbd>⌘ K</kbd></div>${I('doc',18)}<span class="account">K</span></header><div class="shell">${sidebar()}<main><div class="page">${header()}${content()}<div class="foot"><span>${I('info',12)} ${S.role?E(S.role)+'-role coverage':'Coverage'} is scheduled, not live attendance. ${S.query?'Employee search doesn’t change coverage.':''}</span><span>${M.locations[S.location].timezone} · Planned hours exclude assigned unpaid breaks.</span></div>${printable()}</div><div class="below"><span>Sample data · Demo clock: Tue 10 Nov 2026, 1:30 PM · ${S.team} employees${S.permission==='viewer'?' · View only':''}</span><span class="row">${B('Demo controls','demo','ghost small')}${B(I('code',12)+'Developer handoff','handoff','small')}</span></div></main></div>`;
 let vp2=document.getElementById('viewport');if(vp2&&scroll&&!initialScroll){vp2.scrollTop=scroll.top;vp2.scrollLeft=scroll.left;}if(vp2&&initialScroll){initialScroll=false;if(S.view==='week'&&M.week(S.week).includes(M.today)){const row=document.querySelector(`.week-row[data-day="${M.today}"]`);if(row)vp2.scrollTop=Math.max(0,row.offsetTop-76);}}
 if(focus){let target=document.getElementById(focus.id);if(target){target.focus({preventScroll:true});try{target.setSelectionRange(focus.start,focus.end)}catch{}}}renderLayers();persist();}
function remember(){const el=document.activeElement;restoreFocus=el&&el.dataset?{action:el.dataset.action,id:el.dataset.id,key:el.dataset.key}:null;}
function openModal(type,data={}){remember();pop=null;modal={type,...data};if(type==='employee'){modal.color=M.emp(S,data.id).color;}if(type==='timecard'){let x=M.findShift(S,data.id);modal.draft=structuredClone(M.getTimecard(S,x)||{sessions:[],breaks:[],report:null});modal.original=structuredClone(modal.draft);}renderLayers();setTimeout(()=>layers.querySelector('.dialog input:not([disabled]),.dialog select,.dialog .btn')?.focus(),0);}
function closeLayers(){modal=null;pop=null;renderLayers();if(restoreFocus){let q=`[data-action="${restoreFocus.action}"]${restoreFocus.id?`[data-id="${restoreFocus.id}"]`:''}`;document.querySelector(q)?.focus({preventScroll:true});}}
function openPop(type,target,data={}){remember();modal=null;const r=target.getBoundingClientRect();pop={type,x:Math.max(12,Math.min(innerWidth-402,r.left)),y:Math.min(innerHeight-400,Math.max(65,r.bottom+8)),...data};renderLayers();setTimeout(()=>layers.querySelector('.popover input,.popover button')?.focus(),0);}
function dialog(title,body,footer='',wide=false,sub=''){return `<div class="overlay" data-overlay="true"><section class="dialog ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="dialogTitle"><header class="dialog-head"><div><h2 id="dialogTitle">${title}</h2>${sub?`<p>${sub}</p>`:''}</div>${B(I('x'),'close','ghost icon','aria-label="Close dialog"')}</header>${body.startsWith('<nav')?body:`<div class="dialog-body">${body}</div>`}${footer?`<footer class="dialog-foot">${footer}</footer>`:''}</section></div>`;}
function errorBlock(){return '<div id="formError" class="error-message" role="alert"></div><div id="formWarnings" class="help" style="margin-top:8px"></div>';}
function shiftForm(){const x=modal.id?M.findShift(S,modal.id):null,f=modal.formSnapshot,day=f?.day||x?.day||modal.day||S.day,empId=f?.emp||x?.emp||modal.emp||M.people(S)[0]?.id,start=f?M.parseTime(f.start):(x?.start??modal.start??540),end=f?M.parseTime(f.end):(x?.end??modal.end??1020),plan=f?[...(f.rest?[{paid:true}]:[]),...(f.lunch?[{paid:false}]:[])]:x?.plannedBreaks||M.plannedBreaks(end-start);return dialog(x?'Manage Shift':'Add Shift',`<form id="shiftForm"><div class="row" style="margin-bottom:18px">${av(M.emp(S,empId))}<div><b>${E(M.emp(S,empId).name)}</b><div class="help">${M.formatDate(day,{weekday:'long',day:'numeric',month:'short',year:'numeric'})} · ${M.locations[S.location].name}</div></div></div><div class="formgrid">${!x?`<div class="fg full"><label for="shiftEmployee">Employee</label><select class="input" name="emp" id="shiftEmployee">${M.people(S).map(e=>`<option value="${e.id}" ${empId===e.id?'selected':''}>${E(e.name)}</option>`).join('')}</select></div><div class="fg full"><label for="shiftDate">Date</label><input type="date" id="shiftDate" name="day" class="input" value="${day}"></div>`:`<input type="hidden" name="emp" value="${empId}"><input type="hidden" name="day" value="${day}">`}<div class="fg"><label for="shiftStart">Start time</label><input class="input" id="shiftStart" name="start" type="time" step="60" value="${M.inputTime(start)}"></div><div class="fg"><label for="shiftEnd">End time</label><input class="input" id="shiftEnd" name="end" type="time" step="60" value="${M.inputTime(end)}"></div><div class="full"><label class="help"><b>Planned breaks</b> · for estimates, not recorded attendance</label><label class="checkrow"><input type="checkbox" name="rest" ${plan.some(b=>b.paid)?'checked':''}>Rest · 15 min paid · available after 2h</label><label class="checkrow"><input type="checkbox" name="lunch" ${plan.some(b=>!b.paid)?'checked':''}>Lunch · 30 min unpaid · available after 4h</label></div><div class="fg full"><label for="applyShift">Apply to</label><select id="applyShift" name="apply" class="input"><option value="once" ${f?.apply!=='recurring'?'selected':''}>Only this date</option><option value="recurring" ${f?.apply==='recurring'?'selected':''}>This weekday from this date onward</option></select><span class="help">Past schedules and recorded time never change.</span></div></div>${errorBlock()}</form>`,(x?B(I('trash',13)+'Delete shift','deletePrompt','danger small push',`data-id="${x.id}"`):'')+B('Cancel','close')+B('Save changes','saveShift','primary'));}
function readTimecard(){let form=document.getElementById('timecardForm');if(!form)return modal.draft;let draft=structuredClone(modal.draft);form.querySelectorAll('[data-session]').forEach(el=>{draft.sessions[Number(el.dataset.session)][el.dataset.part]=M.parseTime(el.value)});form.querySelectorAll('[data-break]').forEach(el=>{draft.breaks[Number(el.dataset.break)][el.dataset.part]=M.parseTime(el.value)});return draft;}
function tcTotals(t){let span=t.sessions.reduce((n,x)=>n+(Number.isFinite(x.end-x.start)?Math.max(0,x.end-x.start):0),0),paidBreak=t.breaks.reduce((n,x)=>n+M.breakAllocation(x).paid,0),unpaid=t.breaks.reduce((n,x)=>n+M.breakAllocation(x).unpaid,0);return{paid:Math.max(0,span-unpaid),paidBreak,unpaid};}
function tcSummary(t){let a=tcTotals(t);return `<div><small>Recorded paid hours</small><b>${M.dur(a.paid)}</b></div><div><small>Paid breaks · included</small><b>${M.dur(a.paidBreak)}</b></div><div><small>Unpaid breaks</small><b>${M.dur(a.unpaid)}</b></div>`;}
function timecardModal(){let x=M.findShift(S,modal.id),e=M.emp(S,x.emp),t=modal.draft,a=M.attendance(S,x),readonly=!editAllowed(),attr=readonly?'disabled':'';const section=(paid)=>`<h3 style="font-size:12px;margin-top:15px">${paid?'Paid':'Unpaid'} breaks</h3>${t.breaks.map((b,i)=>b.paid===paid?`<div class="session-row"><label><small>${E(b.name)}${b.paidAllowance!=null?' · '+b.paidAllowance+'m paid allowance':b.source==='manual'?' · manual':' · started'}</small><input class="input" type="time" step="60" data-break="${i}" data-part="start" value="${Number.isFinite(b.start)?M.inputTime(b.start):''}" ${attr}></label><label><small>Ended</small><input class="input" type="time" step="60" data-break="${i}" data-part="end" value="${Number.isFinite(b.end)?M.inputTime(b.end):''}" ${attr}></label>${!readonly?B(I('trash',13),'removeBreak','ghost icon',`data-index="${i}" aria-label="Remove ${E(b.name)} record"`):''}</div>`:'').join('')}${!readonly?B(I('plus',12)+'Add '+(paid?'paid':'unpaid')+' break','addBreak','ghost small',`data-paid="${paid}"`):''}`;
 return dialog('Time Card',`<div class="row between" style="margin-bottom:15px"><div class="row">${av(e)}<div><b>${E(e.name)}</b><div class="help">${M.formatDate(x.day,{weekday:'short',month:'short',day:'numeric',year:'numeric'})}</div></div><span class="help">${I('pin',12)} ${M.locations[S.location].name}</span></div><div class="callout info" style="margin-bottom:14px">Scheduled: <b>${range(x)}</b> · The schedule stays unchanged.</div>${t.report&&!t.report.resolved?`<div class="callout" style="margin-bottom:14px"><strong>Employee reported working later</strong>Worked past ${M.time(t.report.after)} · reported at ${M.time(t.report.reportedAt)}.<br>Confirm the finish time and update the clock-out. The report time is not a verified finish time.</div>`:''}${a.flags.length?`<div class="help" style="margin-bottom:12px">${I('alert',12)} ${a.flags.map(E).join(' · ')}</div>`:''}<div class="summary3" id="tcSummary">${tcSummary(t)}</div><form id="timecardForm" data-record="${x.id}"><h3 style="font-size:13px">Work sessions</h3>${t.sessions.map((v,i)=>`<div class="session-row"><label><small>Clocked in${i?' · session '+(i+1):''}</small><input class="input" type="time" step="60" data-session="${i}" data-part="start" value="${Number.isFinite(v.start)?M.inputTime(v.start):''}" ${attr}></label><label><small>Clocked out${v.auto?' · automatic':''}</small><input class="input" type="time" step="60" data-session="${i}" data-part="end" value="${Number.isFinite(v.end)?M.inputTime(v.end):''}" ${attr}></label>${!readonly?B(I('trash',13),'removeSession','ghost icon',`data-index="${i}" aria-label="Remove session ${i+1}"`):''}</div>`).join('')}${!readonly?B(I('plus',12)+'Add a session','addSession','ghost small'):''}<p class="help" style="margin:6px 0">Gaps between sessions are off-clock time, not breaks. Recorded paid breaks keep their original allowance; overage is unpaid. Manually added paid breaks are paid in full.</p><hr class="divider">${section(true)}${section(false)}${!readonly?`<hr class="divider"><div class="fg"><label for="correctionReason">Correction note <span class="help">(optional)</span></label><textarea class="input" id="correctionReason" rows="2" placeholder="e.g. Confirmed the finish time with the employee">${E(modal.reason||'')}</textarea></div>${t.report&&!t.report.resolved?`<label class="checkrow"><input type="checkbox" id="resolveReport" ${modal.resolve?'checked':''}>I reviewed the employee’s report.</label>`:''}<p class="help" style="margin-top:10px">Changes affect recorded hours only after you save. The original records stay in edit history.</p>`:''}${errorBlock()}</form>${S.audit.filter(v=>v.id===x.id).length?`<hr class="divider"><h3 style="font-size:12px">Edit history</h3>${S.audit.filter(v=>v.id===x.id).map(v=>`<div class="auditline">${E(v.text)} · Manager · ${E(v.when)}</div>`).join('')}`:''}`,B(readonly?'Done':'Cancel','close')+(!readonly?B('Update time card','saveTimecard','primary'):''));}
function employeeModal(){let e=M.emp(S,modal.id),owner=S.permission==='owner';return dialog('Edit Employee',`<div class="row" style="border-bottom:1px solid var(--line);margin-bottom:18px;padding-bottom:10px"><b class="text-blue">Basic Details</b><span class="text-muted">Shift Details</span></div><div class="row" style="margin-bottom:16px">${av(e)}<div><h3>${E(e.name)}</h3><small class="text-muted">${E(e.roles.join(', '))}</small></div></div><div class="fg"><label>Works at</label><div class="input">Grocery Mart · Corner Store</div></div><hr class="divider"><h3>Schedule color</h3><p class="help" style="margin-top:5px">Used on this employee’s initials in all schedule views. Adding employees won’t change existing colors.</p><div class="swatches">${M.palette.map((c,i)=>`<button class="swatch" data-action="color" data-color="${i}" aria-label="${c[0]} schedule color" aria-pressed="${modal.color===i}" ${!owner?'disabled':''}><span class="disc" style="background:${c[1]}">${modal.color===i?I('check',15):''}</span>${c[0]}</button>`).join('')}</div><p class="help" style="margin-top:15px">Colors can repeat across a large team. Names and initials always identify the person.${!owner?' Only an owner can change the schedule color.':''}</p>`,B('Cancel','close')+(owner?B('Save changes','saveEmployee','primary'):''),'', 'HR → Employees → Basic Details');}
function closuresModal(){let arr=M.closures(S).filter(c=>c.location===S.location);return dialog('Store closures',`<p class="help">${M.locations[S.location].name} · Closed days appear consistently in all three views.</p>${arr.map(c=>`<div class="closure-row">${I('calendar',20)}<div class="who"><b>${E(c.name)}</b><small class="text-muted">${M.formatDate(c.date)} · ${c.annual?'Repeats yearly':'One-time'}</small></div>${editAllowed()&&c.date>M.today?B(I('trash',13),'deleteClosure','ghost small',`data-id="${c.id}" aria-label="Remove ${E(c.name)}"`):''}</div>`).join('')||'<p style="margin:25px 0">No upcoming store closures.</p>'}`,B('Done','close')+(editAllowed()?B(I('plus',13)+'Add store closure','addClosure','primary'):''));}
const scenarios=[['normal','Default schedule','Common shifts, attendance flags and a reported correction'],['short','Short shifts','5-, 15- and 25-minute shifts with external labels'],['staggered','Staggered starts','Dense groups and individual time ranges'],['closurework','Closed-day work','An intentional one-time shift on Thursday'],['edgehours','Extended hours','00:30 start and 23:59 end'],['historical','Historical changes','Past retained; future employee/location assignments removed'],['nosetup','No usual hours','Clean first-time setup state'],['emptyweek','Empty week','No shifts in the selected week'],['noemployees','No employees','Nothing assigned to this location'],['loading','Loading','Skeleton, then loaded schedule'],['error','Load error','Retry without substituting false zero values'],['saveerror','Save error','First save fails safely; retry keeps entered values'],['disabled','Tracking off','Feature-disabled state']];
function notesBody(){if(tab==='audit')return `<div class="callout info" style="margin-bottom:14px"><strong>Original ticket → current prototype</strong>Implemented, refined, and integration-only requirements are distinguished below. This is a UI handoff; backend readiness is not implied.</div><table class="note-table"><thead><tr><th>ID</th><th>Ticket requirement</th><th>Result</th><th>Behavior / verification</th></tr></thead><tbody>${H.audit.map(r=>`<tr><td>${r[0]}</td><td>${r[1]}</td><td><span class="badge ${r[2]==='Implemented'?'ok':r[2]==='Refined'?'flag':''}">${r[2]}</span></td><td>${r[3]}<p class="help" style="margin-top:6px">${r[4]}</p></td></tr>`).join('')}</tbody></table>`;if(tab==='states')return `<table class="note-table"><thead><tr><th>State</th><th>Design behavior</th><th>How to preview</th></tr></thead><tbody>${H.states.map(r=>`<tr>${r.map(v=>`<td>${v}</td>`).join('')}</tr>`).join('')}</tbody></table>`;return H[tab]||'';}
function modalHtml(){if(!modal)return'';if(modal.type==='shift')return shiftForm();if(modal.type==='timecard')return timecardModal();if(modal.type==='employee')return employeeModal();if(modal.type==='closures')return closuresModal();if(modal.type==='handoff')return dialog('Developer handoff',`<nav class="notes-tabs" aria-label="Handoff sections">${[['audit','Ticket audit'],['behavior','Behavior rules'],['states','State matrix'],['data','Data & integration'],['qa','QA & limits']].map(([k,n])=>`<button class="${tab===k?'active':''}" data-action="noteTab" data-tab="${k}">${n}</button>`).join('')}</nav><div class="dialog-body notes">${notesBody()}</div>`,B('Export ticket audit','exportAudit','push')+B('Done','close','primary'),true,H.version);
 if(modal.type==='delete'){let x=M.findShift(S,modal.id);return dialog('Delete this shift?',`<p><b>${E(M.emp(S,x.emp).name)}</b> · ${M.formatDate(x.day)}</p><p style="margin:12px 0">${range(x)}</p><p class="help">Only this future shift will be removed. Usual working hours and past Time Cards stay unchanged.</p>`,B('Cancel','close')+B('Delete shift','confirmDelete','danger'));}
 if(modal.type==='removeBreak')return dialog('Remove this recorded break?',`<p>Removing this break can change recorded paid hours. The original scheduled break will stay unchanged.</p><p class="help" style="margin-top:12px">The removal is saved only when you update the Time Card.</p>`,B('Cancel','cancelRemoveBreak')+B('Remove break','confirmRemoveBreak','danger'));
 if(modal.type==='addClosure')return dialog('Add Store Closure',`<form id="closureForm" class="formgrid"><div class="fg full"><label for="closureName">Occasion</label><input class="input" id="closureName" name="name" maxlength="60" placeholder="e.g. Maintenance day"></div><div class="fg full"><label for="closureDate">Date</label><input class="input" id="closureDate" name="date" type="date" min="${M.add(M.today,1)}" value="${M.add(M.today,3)}"></div><label class="checkrow full"><input type="checkbox" name="annual">Repeats every year <span title="Creates this store closure on the same date every year.">${I('info',13)}</span></label><div class="help full">Future usual-hour shifts on this date will be removed from the schedule. One-time working exceptions remain visible. Recorded time won’t change.</div><div class="full">${errorBlock()}</div></form>`,B('Cancel','close')+B('Continue','saveClosure','primary'));
 if(modal.type==='confirmClosure')return dialog('Add this store closure?',`<p><b>${E(modal.data.name)}</b> · ${M.formatDate(modal.data.date)}</p><div class="callout" style="margin-top:14px">${modal.count} future usual-hour ${modal.count===1?'shift will':'shifts will'} be removed for this date. Explicit one-time shifts stay visible. Past schedules and Time Cards won’t change.</div>`,B('Cancel','close')+B('Add closure','confirmClosure','primary'));
 if(modal.type==='deleteClosure'){let c=M.closures(S).find(v=>v.id===modal.id);return dialog('Remove store closure?',`<p><b>${E(c?.name)}</b> · ${M.formatDate(c.date)}</p><p class="help" style="margin-top:12px">Future shifts from usual working hours can appear again. Previously deleted individual shifts and past records won’t change.</p>`,B('Cancel','close')+B('Remove closure','confirmDeleteClosure','danger'));}
 if(modal.type==='date')return dialog(S.view==='day'?'Go to date':'Choose work week',`<div class="fg"><label for="jumpDate">${S.view==='day'?'Date':'Select any day in the week'}</label><input class="input" id="jumpDate" type="date" value="${S.view==='day'?S.day:S.week}"><p class="help">${S.view==='day'?'Dates use the location’s local calendar.':'The selected Monday–Sunday work week will be shown.'}</p></div>`,B('Cancel','close')+B('Go','jumpDate','primary'));
 if(modal.type==='download')return dialog('Download schedule',`<p>${M.locations[S.location].name} · ${M.formatDate(S.week)}–${M.formatDate(M.add(S.week,6))}</p><div class="callout info" style="margin-top:15px">Exports follow the selected location, week and employee/role filters. Highlights do not filter the export. Hours and costs are planned estimates, not actual payroll.</div>`,B(I('print',14)+'Print schedule','print','push')+B('Cancel','close')+B(I('download',14)+'Download CSV','csv','primary'));
 if(modal.type==='demo')return dialog('Prototype scenarios',`<div class="callout info" style="margin-bottom:15px">Fixed demo clock: Tue 10 Nov 2026, 1:30 PM · America/Phoenix. Changes are stored in this browser only.</div><div class="formgrid" style="margin-bottom:18px"><label class="fg">Team size<select id="teamSize" class="input">${[5,12,24,72].map(n=>`<option value="${n}" ${S.team===n?'selected':''}>${n} employees</option>`).join('')}</select></label><label class="fg">Permission<select id="permission" class="input">${[['owner','Owner'],['manager','Manager'],['viewer','View only']].map(([v,n])=>`<option value="${v}" ${S.permission===v?'selected':''}>${n}</option>`).join('')}</select></label></div><div class="scenario-grid">${scenarios.map(([v,t,d])=>`<button class="scenario-btn ${S.scenario===v?'active':''}" data-action="scenario" data-scenario="${v}"><b>${t}</b><small>${d}</small></button>`).join('')}</div>`,B('Reset demo','reset','danger small push')+B('Add sample employee','hire','small')+B('Done','close','primary'),true);
 if(modal.type==='route')return dialog(modal.title,`<p>${modal.text}</p>${modal.employees?`<div class="modalList" style="margin-top:15px">${M.people(S).map(e=>`<div class="popitem">${av(e)}<div class="who"><b>${E(e.name)}</b><small>${E(e.roles.join(', '))}</small></div>${B('Edit employee','employee','small',`data-id="${e.id}"`)}</div>`).join('')}</div>`:''}`,B('Done','close','primary'));
 return '';}
function popHtml(){if(!pop)return'';let content='';if(pop.type==='highlights'){let p=M.people(S).filter(e=>!pop.query||e.name.toLowerCase().includes(pop.query.toLowerCase()));content=`<div class="pophead"><div><h3>Highlight employees</h3><small>Select several people. Everyone else stays visible.</small></div>${B(I('x'),'closePop','ghost icon','aria-label="Close employee picker"')}</div><label class="searchbox">${I('search',13)}<input id="highlightSearch" type="search" placeholder="Find an employee" value="${E(pop.query||'')}"></label><div class="poplist">${p.map(e=>`<button class="membercheck" data-action="highlight" data-id="${e.id}" aria-pressed="${sel(e.id)}">${av(e)}<b>${E(e.name)}</b><span class="tickcheck">${sel(e.id)?I('check',11):''}</span></button>`).join('')||'<p class="help" style="padding:18px 0">No employees found.</p>'}</div><div class="popfoot"><span class="help">${S.highlights.length} highlighted</span><button class="link" data-action="clearHighlight">Clear all</button></div>`;}
 if(pop.type==='group'){let g=M.groups(S,pop.day).find(g=>g.key===pop.key);if(!g){pop=null;return'';}let stat=statusForGroup(g);content=`<div class="pophead"><div><h3>${range(g)}</h3><small>${M.formatDate(pop.day)} · ${g.items.length} ${g.items.length===1?'employee':'employees'}${g.type==='one-time'?' · One-time':''}</small><div class="row" style="margin-top:5px">${stat.review?`<span class="badge review">${stat.review} needs review</span>`:''}${stat.flag?`<span class="badge flag">${stat.flag} attendance ${stat.flag===1?'flag':'flags'}</span>`:''}</div></div>${B(I('x'),'closePop','ghost icon','aria-label="Close shift group"')}</div><div class="poplist">${g.items.map(x=>{let e=M.emp(S,x.emp),a=M.attendance(S,x),future=M.canEdit(x);return `<div class="popitem">${av(e)}<div class="who"><b>${E(e.name)}</b><small>${E(e.roles.join(', '))}</small>${a.kind!=='none'?`<small style="color:${a.kind==='ok'?'var(--green)':'#9f6b2a'}">${E(a.kind==='ok'?'Recorded':a.text)}</small>`:''}</div>${B(future?(editAllowed()?'Edit shift':'View shift'):'View Time Card','shift','small',`data-id="${x.id}"`)}</div>`;}).join('')}</div><div class="popfoot"><span class="help">Planned times · not recorded sessions</span><button class="link" data-action="openDay" data-day="${pop.day}">Open day ${I('right',12)}</button></div>`;}
 if(pop.type==='gap'){let text=S.role?`No ${S.role.toLowerCase()}-role employees scheduled`:'No employees scheduled';content=`<div class="pophead"><div><h3>${text}</h3><small>${M.formatDate(pop.day)} · ${M.time(pop.start)}–${M.time(pop.end)}</small></div>${B(I('x'),'closePop','ghost icon','aria-label="Close coverage gap"')}</div><div style="padding:15px"><p class="help">This is a gap in scheduled coverage during store opening hours. It is not a live attendance count.${S.role?' Employee roles describe membership, not a dedicated shift assignment.':''}</p></div><div class="popfoot">${B('Open day','openDay','small',`data-day="${pop.day}"`)}${editAllowed()&&pop.day>=M.today?B('Add shift','addShift','primary small',`data-day="${pop.day}" data-start="${pop.start}" data-end="${pop.end}"`):''}</div>`;}
 if(pop.type==='time'){let day=S.view==='day'?S.day:pop.day||M.today,arr=M.shifts(S,day,true).filter(x=>x.start<=pop.time&&x.end>pop.time),un=[...new Map(arr.map(x=>[x.emp,x])).values()];content=`<div class="pophead"><div><h3>Scheduled at ${M.time(pop.time)}</h3><small>${M.formatDate(day)} · ${un.length} employees${S.query||S.role?' · current filters':''}</small></div>${B(I('x'),'closePop','ghost icon','aria-label="Close time details"')}</div><div class="poplist">${un.map(x=>`<div class="popitem">${av(M.emp(S,x.emp))}<div class="who"><b>${E(M.emp(S,x.emp).name)}</b><small>${range(x)}</small></div>${B(I('right',12),'shift','small',`data-id="${x.id}" aria-label="View shift"`)}</div>`).join('')||'<p class="help" style="padding:20px 0">No matching employees scheduled at this time.</p>'}</div>`;}
 if(pop.type==='timeoff'){let arr=M.timeOff(S,pop.day);content=`<div class="pophead"><div><h3>Time off</h3><small>${M.formatDate(pop.day)}</small></div>${B(I('x'),'closePop','ghost icon','aria-label="Close time off"')}</div><div class="poplist">${arr.map(o=>`<div class="popitem">${av(M.emp(S,o.emp))}<div class="who"><b>${E(M.emp(S,o.emp).name)}</b><small>${E(o.label)}</small></div></div>`).join('')}</div>`;}
 return `<section class="popover" style="left:${pop.x}px;top:${Math.max(60,pop.y)}px" role="dialog" aria-label="${pop.type==='highlights'?'Highlight employees':'Schedule details'}">${content}</section>`;}
function renderLayers(){let f=document.activeElement,selection=f?.id?{id:f.id,start:f.selectionStart,end:f.selectionEnd}:null;layers.innerHTML=modal?modalHtml():pop?popHtml():'';if(selection){let el=layers.querySelector('#'+selection.id);if(el){el.focus({preventScroll:true});try{el.setSelectionRange(selection.start,selection.end)}catch{}}}}
function formErrors(errors,warnings=[]){document.getElementById('formError').innerHTML=errors.map(E).join('<br>');let el=document.getElementById('formWarnings');if(el)el.innerHTML=warnings.map(w=>'• '+E(w)).join('<br>');}
function readShift(){let f=new FormData(document.getElementById('shiftForm')),start=M.parseTime(f.get('start')),end=M.parseTime(f.get('end')),p=[];if(f.has('rest'))p.push({name:'Rest',duration:15,paid:true,after:120});if(f.has('lunch'))p.push({name:'Lunch',duration:30,paid:false,after:240});return {emp:f.get('emp'),day:f.get('day'),start,end,plannedBreaks:p,apply:f.get('apply'),location:S.location};}
function saveShift(){if(!editAllowed())return notify('You have view-only access.');let x=readShift(),v=M.shiftValidation(S,x,modal.id);if(!x.day)v.errors.push('Choose a date.');else if(x.day<M.today||x.day===M.today&&x.start<=M.now)v.errors.push('Use a future start time. Recorded work is corrected in the Time Card.');if(!x.emp)v.errors.push('Choose an employee.');if(v.errors.length){formErrors(v.errors,v.warnings);return;}if(v.warnings.length&&!modal.confirmedWarnings){formErrors([],v.warnings);document.getElementById('formWarnings').innerHTML+='<p style="margin-top:8px"><label class="checkrow"><input type="checkbox" id="confirmShiftWarnings">I’ve checked these details. Save this shift.</label></p>';modal.confirmedWarnings=true;return;}if(v.warnings.length&&!document.getElementById('confirmShiftWarnings')?.checked){formErrors(['Confirm the warnings before saving.'],v.warnings);modal.confirmedWarnings=false;return;}if(S.scenario==='saveerror'&&!modal.saveFailed){modal.saveFailed=true;formErrors(['Changes couldn’t be saved. Nothing was updated. Try again.']);return;}let original=modal.id?M.findShift(S,modal.id):null;let type=M.closure(S,x.day)||x.apply==='once'?'one-time':'scheduled';let data={...x,type,source:x.apply==='once'?'manual':'usual'};delete data.apply;
 if(x.apply==='recurring'){S.recurring.push({...data,weekday:M.weekday(x.day),from:x.day});}
 if(original)S.overrides[original.id]={...data,id:original.id};else S.added.push({...data,id:'manual-'+Date.now()});if(S.scenario==='emptyweek'){}modal=null;pop=null;S.day=x.day;S.week=M.weekStart(x.day);render();notify('Shift saved. All views use the updated schedule.');}
function saveTimecard(){if(!editAllowed())return;let t=readTimecard(),errors=M.timecardValidation(t);if(errors.length){formErrors(errors);return;}if(S.scenario==='saveerror'&&!modal.saveFailed){modal.saveFailed=true;formErrors(['Changes couldn’t be saved. Nothing was updated. Try again.']);return;}let x=M.findShift(S,modal.id),note=document.getElementById('correctionReason').value.trim(),resolve=document.getElementById('resolveReport')?.checked;if(t.report&&resolve)t.report.resolved=true;t.missing=false;t.sessions=t.sessions.map((q,i)=>({...q,auto:modal.original.sessions[i]?.end===q.end?q.auto:false}));S.timecards[x.id]=t;S.audit.push({id:x.id,when:new Date().toLocaleString(),text:note||'Recorded work sessions or breaks updated',before:modal.original,after:structuredClone(t)});modal=null;render();notify('Time card updated. Recorded hours recalculated; schedule unchanged.');}
function saveClosure(){if(!editAllowed())return;let f=new FormData(document.getElementById('closureForm')),d={id:'closure-'+Date.now(),name:String(f.get('name')).trim(),date:f.get('date'),annual:f.has('annual'),location:S.location};if(!d.name||!d.date||d.date<=M.today){formErrors(['Add an occasion and choose a future date.']);return;}if(M.closures(S).some(c=>c.location===d.location&&c.date===d.date)){formErrors(['A store closure already exists on this date.']);return;}let count=M.shifts(S,d.date).filter(x=>x.type==='scheduled').length;openModal('confirmClosure',{data:d,count});}
function csvDownload(filename,rows){const safe=x=>{let str=String(x??'');if(/^[=+@]/.test(str))str="'"+str;return '"'+str.replaceAll('"','""')+'"';},text='\ufeff'+rows.map(r=>r.map(safe).join(',')).join('\r\n'),url=URL.createObjectURL(new Blob([text],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
function exportSchedule(){const rows=[['Date','Location','Employee','Employee roles','Scheduled start','Scheduled end','Source','Planned paid minutes','Estimated labor cost','Attendance','Note']];M.week(S.week).forEach(day=>M.shifts(S,day,true).forEach(x=>{let e=M.emp(S,x.emp),a=M.attendance(S,x),p=M.totals(S,x).paid;rows.push([day,M.locations[S.location].name,e.name,e.roles.join('; '),M.time(x.start),M.time(x.end),x.type,p,(p/60*e.wage).toFixed(2),a.kind,a.kind==='none'?'':a.text]);}));csvDownload('OctoPOS-schedule-'+S.week+'.csv',rows);notify('Schedule CSV downloaded.');}
function viewShift(id){let x=M.findShift(S,id);if(!x)return notify('This shift is no longer available.');if(M.canEdit(x)){if(editAllowed())openModal('shift',{id});else openModal('route',{title:'Scheduled shift',text:`${E(M.emp(S,x.emp).name)} · ${M.formatDate(x.day)} · ${range(x)}. You have view-only access.`});}else openModal('timecard',{id});}
function changeView(v){S.view=v;if(v==='day'&&!M.week(S.week).includes(S.day))S.day=M.week(S.week).includes(M.today)?M.today:S.week;pop=null;initialScroll=true;render();}
function updateTcPreview(){if(!modal||modal.type!=='timecard')return;let t=readTimecard();document.getElementById('tcSummary').innerHTML=tcSummary(t);document.getElementById('formWarnings').innerHTML='Preview only. Update the Time Card to save these changes.';}

function captureDraft(){
 if(modal?.type==='timecard'){
  const form=document.getElementById('timecardForm');
  if(form&&form.dataset.record===modal.id){modal.draft=readTimecard();modal.reason=document.getElementById('correctionReason')?.value||'';modal.resolve=document.getElementById('resolveReport')?.checked||false;}
 }
 if(modal?.type==='shift'&&document.getElementById('shiftForm')){
  const f=new FormData(document.getElementById('shiftForm'));modal.formSnapshot={...Object.fromEntries(f),rest:f.has('rest'),lunch:f.has('lunch')};
 }
}

function handleClick(event){const b=event.target.closest('[data-action]');if(!b){if(pop&&!event.target.closest('.popover')){pop=null;renderLayers();}return;}const a=b.dataset.action;captureDraft();event.preventDefault();switch(a){
 case 'view':changeView(b.dataset.view);break;
 case 'home':S.view='week';render();break;
 case 'prev':case 'next':{let delta=a==='prev'?-1:1;if(S.view==='day'){S.day=M.add(S.day,delta);S.week=M.weekStart(S.day);}else{S.week=M.add(S.week,delta*7);S.day=S.week;}initialScroll=true;pop=null;render();break;}
 case 'today':S.week=M.anchor;S.day=M.today;initialScroll=true;render();break;
 case 'date':openModal('date');break;
 case 'jumpDate':{let d=document.getElementById('jumpDate').value;if(d){S.week=M.weekStart(d);S.day=d;modal=null;initialScroll=true;render();}break;}
 case 'openDay':S.day=b.dataset.day;S.week=M.weekStart(S.day);S.view='day';pop=null;initialScroll=true;render();break;
 case 'toggleFilters':S.filtersOpen=!S.filtersOpen;render();if(S.filtersOpen)document.getElementById('employeeSearch')?.focus();break;
 case 'clearFilters':S.role='';S.query='';render();break;
 case 'highlight':{let id=b.dataset.id;S.highlights=sel(id)?S.highlights.filter(x=>x!==id):[...S.highlights,id];render();if(!pop)document.querySelector(`[data-action="highlight"][data-id="${id}"]`)?.focus({preventScroll:true});break;}
 case 'clearHighlight':S.highlights=[];render();break;
 case 'morePeople':openPop('highlights',b,{query:''});break;
 case 'closePop':pop=null;renderLayers();break;
 case 'group':openPop('group',b,{day:b.dataset.day,key:b.dataset.key});break;
 case 'gap':openPop('gap',b,{day:b.dataset.day,start:+b.dataset.start,end:+b.dataset.end});break;
 case 'inspectTime':openPop('time',b,{time:+b.dataset.time,day:S.view==='day'?S.day:(M.week(S.week).includes(M.today)?M.today:S.week)});break;
 case 'timeoff':openPop('timeoff',b,{day:b.dataset.day});break;
 case 'shift':viewShift(b.dataset.id);break;
 case 'addShift':if(editAllowed()){const day=b.dataset.day||S.day;openModal('shift',{day,emp:b.dataset.emp,start:b.dataset.start?+b.dataset.start:undefined,end:b.dataset.end?+b.dataset.end:undefined});}break;
 case 'saveShift':saveShift();break;
 case 'deletePrompt':{let x=M.findShift(S,b.dataset.id);if(editAllowed()&&M.canEdit(x))openModal('delete',{id:x.id});break;}
 case 'confirmDelete':{let x=M.findShift(S,modal.id);if(editAllowed()&&M.canEdit(x)){S.removed.push(x.id);modal=null;render();notify('This future shift was deleted.');}break;}
 case 'collapseGroup':{let id=b.dataset.key;S.closedGroups=S.closedGroups.includes(id)?S.closedGroups.filter(k=>k!==id):[...S.closedGroups,id];render();break;}
 case 'toggleFree':S.showFree=!S.showFree;render();break;
 case 'toggleOff':S.showOff=!S.showOff;render();break;
 case 'employee':openModal('employee',{id:b.dataset.id});break;
 case 'color':if(S.permission==='owner'){modal.color=+b.dataset.color;renderLayers();layers.querySelector(`[data-action="color"][data-color="${modal.color}"]`)?.focus();}break;
 case 'saveEmployee':if(S.permission==='owner'){S.colorOverrides[modal.id]=modal.color;modal=null;render();notify('Schedule color saved for this employee.');}break;
 case 'closures':openModal('closures');break;
 case 'addClosure':if(editAllowed())openModal('addClosure');break;
 case 'saveClosure':saveClosure();break;
 case 'confirmClosure':if(editAllowed()){S.closureOverrides.push(modal.data);modal=null;render();notify('Store closure added. Future schedules updated.');}break;
 case 'deleteClosure':if(editAllowed())openModal('deleteClosure',{id:b.dataset.id});break;
 case 'confirmDeleteClosure':if(editAllowed()){S.removedClosures.push(modal.id);modal=null;render();notify('Closure removed. Future usual-hour shifts restored.');}break;
 case 'download':openModal('download');break;
 case 'csv':exportSchedule();closeLayers();break;
 case 'print':closeLayers();window.print();break;
 case 'handoff':tab='audit';openModal('handoff');break;
 case 'noteTab':tab=b.dataset.tab;renderLayers();layers.querySelector(`[data-tab="${tab}"]`)?.focus();break;
 case 'exportAudit':csvDownload('OctoPOS-ticket-audit.csv',[['ID','Original requirement','Status','Prototype behavior','Integration / refinement'],...H.audit]);break;
 case 'demo':openModal('demo');break;
 case 'scenario':{S.scenario=b.dataset.scenario;S.query='';S.role='';S.highlights=[];S.week=M.anchor;S.day=['short','staggered','edgehours'].includes(S.scenario)?'2026-11-11':S.scenario==='closurework'?'2026-11-12':M.today;modal=null;initialScroll=true;render();if(S.scenario==='loading')setTimeout(()=>{if(S.scenario==='loading'){S.scenario='normal';render();}},1400);break;}
 case 'retry':S.scenario='loading';render();setTimeout(()=>{S.scenario='normal';render();},800);break;
 case 'reset':{let view=S.view;S=M.createState();S.view=view;modal=null;pop=null;initialScroll=true;render();notify('Demo reset to the original sample data.');break;}
 case 'hire':{let id='new-'+Date.now();S.newEmployees.push({id,name:'Riley Morgan',roles:['Cashier'],wage:20,locations:['grocery','corner'],color:(72+S.newEmployees.length)%12});S.scenario='normal';modal=null;render();notify('Riley added. Existing employee colors are unchanged.');break;}
 case 'addSession':modal.draft=readTimecard();modal.reason=document.getElementById('correctionReason')?.value;modal.draft.sessions.push({start:NaN,end:NaN,auto:false});renderLayers();break;
 case 'removeSession':modal.draft=readTimecard();modal.draft.sessions.splice(+b.dataset.index,1);renderLayers();break;
 case 'addBreak':modal.draft=readTimecard();modal.reason=document.getElementById('correctionReason')?.value;modal.draft.breaks.push({name:b.dataset.paid==='true'?'Manual paid break':'Manual unpaid break',paid:b.dataset.paid==='true',source:'manual',start:NaN,end:NaN});renderLayers();break;
 case 'removeBreak':{let old={...modal,draft:readTimecard(),reason:document.getElementById('correctionReason')?.value};modal={type:'removeBreak',previous:old,index:+b.dataset.index};renderLayers();break;}
 case 'cancelRemoveBreak':modal=modal.previous;renderLayers();break;
 case 'confirmRemoveBreak':{let old=modal.previous;old.draft.breaks.splice(modal.index,1);modal=old;renderLayers();break;}
 case 'saveTimecard':saveTimecard();break;
 case 'employees':openModal('route',{title:'Employees',text:'Open an employee’s Basic Details to manage their schedule color. Usual working hours are set in the existing Shift Details tab. This prototype demonstrates the color integration; full employee setup stays in the existing module.',employees:true});break;
 case 'settings':openModal('route',{title:'Time Clock settings',text:'Production destination: Settings → Locations → '+M.locations[S.location].name+' → Time Clock. Turn on Shift tracking there. Use Demo controls → Default schedule to return to the enabled preview.'});break;
 case 'timelineInfo':openModal('route',{title:'Reading the timeline',text:'Bars show planned shifts. Narrow bars keep their real duration and put full times outside the marker. Scroll sideways for later hours; day/employee names and the hour ruler stay fixed. Select any shift or hour for details.'});break;
 case 'nav':openModal('route',{title:b.dataset.name||'OctoPOS navigation',text:'This is the existing OctoPOS navigation destination. The prototype focuses on Employee Schedules; other application modules have not been recreated.'});break;
 case 'close':closeLayers();break;
 }}
document.addEventListener('click',handleClick);
document.addEventListener('input',event=>{let e=event.target;if(e.id==='employeeSearch'){S.query=e.value;render();}else if(e.id==='highlightSearch'){pop.query=e.value;renderLayers();}else if(e.matches('[data-session],[data-break]'))updateTcPreview();else if(e.closest('#shiftForm')&&e.id!=='confirmShiftWarnings'){modal.confirmedWarnings=false;let v=M.shiftValidation(S,readShift(),modal.id);document.getElementById('formWarnings').textContent=v.warnings.join(' ');}});
document.addEventListener('change',event=>{let e=event.target;if(e.id==='location'){S.location=e.value;S.highlights=[];S.query='';S.role='';modal=null;pop=null;initialScroll=true;render();}else if(e.id==='roleFilter'){S.role=e.value;render();}else if(e.id==='teamSize'){S.team=+e.value;S.highlights=[];render();}else if(e.id==='permission'){S.permission=e.value;render();}});
document.addEventListener('submit',event=>{event.preventDefault();if(event.target.id==='shiftForm')saveShift();if(event.target.id==='timecardForm')saveTimecard();if(event.target.id==='closureForm')saveClosure();});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&(modal||pop)){closeLayers();return;}if(e.key==='Tab'&&modal){let focusable=[...layers.querySelectorAll('button:not([disabled]),input:not([disabled]):not([type=hidden]),select:not([disabled]),textarea:not([disabled]),[tabindex="0"]')].filter(n=>n.getClientRects().length);let first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
let resizeTimer;window.addEventListener('resize',()=>{clearTimeout(resizeTimer);resizeTimer=setTimeout(()=>{if(pop){pop.x=Math.max(12,Math.min(innerWidth-402,pop.x));pop.y=Math.max(60,Math.min(innerHeight-400,pop.y));}render();},150)});
window.OctoPOSDemo={getState:()=>structuredClone(S),setState:p=>{Object.assign(S,p);modal=null;pop=null;initialScroll=false;render();},reset:()=>{S=M.createState();modal=null;pop=null;initialScroll=true;render();},model:M,groups:d=>M.groups(S,d),layout:d=>layoutGroups(M.groups(S,d),sizing()),totals:d=>M.aggregate(S,M.shifts(S,d,true)),openTimecard:id=>openModal('timecard',{id}),openShift:id=>viewShift(id)};
render();
})();
